from pathlib import Path
import sys
sys.path.insert(0,str(Path(__file__).resolve().parent.parent/'rain-coupled-reference'))
import model as m
import numpy as np
from scipy.linalg import cho_factor,cho_solve
p=Path(__file__).resolve().parent;free=np.concatenate([np.arange(b['sl'].start,b['sl'].stop) for b in m.blocks if b['domain']=='free']);remaining=np.array([i for i in range(m.offset) if i not in set(free)]);lookup={i:k for k,i in enumerate(remaining)};N=len(remaining);E=np.eye(N)
Hff=m.H[np.ix_(free,free)];Hfr=m.H[np.ix_(free,remaining)];factor=cho_factor(Hff,lower=True);base=-cho_solve(factor,m.g[free]);response=-cho_solve(factor,Hfr);S=m.H[np.ix_(remaining,remaining)]+Hfr.T@response;S=(S+S.T)*.5;q=m.g[remaining]+Hfr.T@base

def recover(y):
 x=np.zeros(m.offset);x[remaining]=y;x[free]=base+response@y;return x
blocks=[]
for b in m.blocks:
 if b['domain']=='free':continue
 ii=np.array([lookup[k] for k in range(b['sl'].start,b['sl'].stop)]);K=S[np.ix_(ii,ii)];eig=np.linalg.eigvalsh(K);assert min(eig)>1e-12
 normals=None if b['normal_indices'] is None else np.array([lookup[k] for k in b['normal_indices']]);blocks.append(dict(original=b,indices=ii,normal_indices=normals,step=1/max(eig),K=K))

def radius(b,y):
 original=b['original']
 if b['normal_indices'] is None:return original['cap']
 return max(0.,float(original['weights']@y[b['normal_indices']]))

def residual(y,jac=False):
 grad=S@y+q;out=np.zeros(N);D=np.zeros((N,N)) if jac else None
 for b in blocks:
  original=b['original'];ii=b['indices'];n=len(ii);step=b['step'];z=y[ii]-step*grad[ii];domain=original['domain'];P=z.copy();Dz=np.eye(n);Dc=np.zeros(n)
  if domain=='positive':P=np.maximum(z,0);Dz=np.diag((z>0).astype(float))
  elif domain=='box':
   cap=radius(b,y);P=np.clip(z,-cap,cap);Dz=np.diag((abs(z)<cap).astype(float));Dc=np.where(abs(z)>=cap,np.sign(z),0)
  elif domain=='ball':
   cap=radius(b,y);length=np.linalg.norm(z)
   if length>cap:u=z/length;P=cap*u;Dz=(cap/length)*(np.eye(n)-np.outer(u,u));Dc=u
  out[ii]=y[ii]-P
  if jac:
   D[ii]=E[ii]-Dz@(E[ii]-step*S[ii])
   if b['normal_indices'] is not None and radius(b,y)>0:D[np.ix_(ii,b['normal_indices'])]-=np.outer(Dc,original['weights'])
 return D if jac else out

