from pathlib import Path
import json,time,numpy as np,scipy
from scipy.optimize import least_squares
from reduced_model import m,p,free,remaining,recover,residual,N,blocks
from wave import wave
rng=np.random.default_rng(20261003);errors=[]
for i in range(24):
 y=m.old[remaining]+.02*rng.normal(size=N);direction=rng.normal(size=N);direction/=np.linalg.norm(direction);eps=1e-6;fd=(residual(y+eps*direction)-residual(y-eps*direction))/(2*eps);pred=residual(y,True)@direction;errors.append(float(np.max(abs(fd-pred)/(1+abs(pred)))))
reference=np.load(m.p/'polished-solution.npz');ref=reference['impulses'];known=residual(ref[remaining]);recovered=recover(ref[remaining]);controls=dict(cases=24,max_directional_error=max(errors),errors=errors,reference_recovery_error=float(np.max(abs(ref-recovered))),reference_reduced_natural_residual=float(np.max(abs(known)/(1+abs(ref[remaining])))),reference_original_natural_residual=float(np.max(abs(m.residual(recovered))/(1+abs(recovered)))))
(p/'controls.json').write_text(json.dumps(controls,indent=2));assert max(errors)<1e-5 and controls['reference_recovery_error']<1e-9 and controls['reference_original_natural_residual']<=1e-8;print('CONTROLS',json.dumps({k:v for k,v in controls.items() if k!='errors'}),flush=True)
results={}
for name,initial in [('cold',np.zeros(N)),('capped',m.old[remaining])]:
 history=[];start=time.monotonic()
 def fun(y):
  r=residual(y);x=recover(y);history.append(dict(evaluation=len(history)+1,reduced_relative_natural_residual=float(np.max(abs(r)/(1+abs(y)))),original_relative_natural_residual=float(np.max(abs(m.residual(x))/(1+abs(x))))));return r
 result=least_squares(fun,initial,jac=lambda y:residual(y,True),method='trf',tr_solver='exact',x_scale='jac',max_nfev=120,ftol=1e-12,xtol=1e-12,gtol=1e-12)
 x=recover(result.x);natural=float(np.max(abs(m.residual(x))/(1+abs(x))));grad=m.gradient_primal(x);dense=m.H@x+m.g;agreement=float(np.max(abs(grad-dense)/(1+np.maximum(abs(grad),abs(dense)))));free_residual=float(np.max(abs(grad[free])/(1+abs(x[free]))));_,sweep=wave(x);feas=[]
 for b in m.blocks:
  val=x[b['sl']];domain=b['domain'];cap=m.radius(b,x);error=0.
  if domain=='positive':error=max(0,-float(min(val)))
  elif domain=='box':error=max(0,float(max(abs(val)))-cap)/(1+cap)
  elif domain=='ball':error=max(0,float(np.linalg.norm(val))-cap)/(1+cap)
  feas.append(error)
 passed=bool(natural<=1e-8 and max(feas)<=1e-8 and agreement<=1e-9 and free_residual<=1e-9 and max(sweep['max_velocity_change'],sweep['max_impulse_change'])<=1e-5)
 output=dict(status='reference-pass' if passed else 'reference-failed',scipy_version=scipy.__version__,seconds=time.monotonic()-start,optimizer=dict(success=bool(result.success),status=int(result.status),message=result.message,nfev=result.nfev,njev=result.njev,cost=float(result.cost),optimality=float(result.optimality)),final_original_relative_natural_residual=natural,maximum_scaled_feasibility_violation=max(feas),direct_primal_agreement=agreement,free_residual=free_residual,original_colored_wave=sweep,reference_velocity_max_difference=float(np.max(abs(m.vfree+m.M@m.J.T@x-reference['velocities']))),reference_impulse_max_difference=float(np.max(abs(x-ref))),history=history)
 results[name]=output;np.savez(p/(name+'-solution.npz'),impulses=x,velocities=m.vfree+m.M@m.J.T@x);(p/'result.json').write_text(json.dumps(dict(scope='Dense exact trust-region reference on reduced fixed-geometry problem; no GPU/physical qualification.',arms=results),indent=2));print(name,json.dumps({k:v for k,v in output.items() if k!='history'}),flush=True)
if not all(r['status']=='reference-pass' for r in results.values()):raise SystemExit(1)
